class Solution {    List<List<int[]>>adj = new ArrayList<>();    public int networkDelayTime(int[][] times, int n, int k) {        for(int i=0; i<=n; i++){            adj.add(new ArrayList<>());        }        for(int i=0; i<times.length; i++){            int u = times[i][0];            int v = times[i][1];            int w = times[i][2];            adj.get(u).add(new int[]{v, w});        }        int distance[] = new int[n+1];        Arrays.fill(distance, Integer.MAX_VALUE);        PriorityQueue<int[]>pq = new PriorityQueue<>((a, b) ->  a[0] - b[0]);        pq.offer(new int[]{k, 0});        distance[k] = 0;        while(!pq.isEmpty()){            int curr[] = pq.poll();            int node = curr[0];            int w = curr[1];            for(int next[] : adj.get(node)){                int u = next[0];                int weight = next[1];                if(w + weight < distance[u]){                    distance[u] = w + weight;                    pq.offer(new int[]{u, w + weight});                }            }        }        for(int val : distance)System.out.print(val + " ");        for(int i=1; i<=n; i++){            if(distance[i] == Integer.MAX_VALUE)return -1;        }        int ans = Integer.MIN_VALUE;        for(int i=1; i<=n; i++){            ans = Math.max(ans, distance[i]);        }        return ans;    }}